import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';

// Story F1 — color tokens and the style-guide catalog.
//
// The new palette is two layers: plain `--palette-*` variables holding the
// raw hex values, and `--color-<style>` styles in @theme that reference a
// variable. Styles must follow their variable live (editing a variable in
// devtools repaints every style using it). The old tokens stay exactly as
// they were. `/style-guide` becomes a plain catalog showing the palette; the
// live token editor is gone. Do not edit this file to match an
// implementation.

const VARIABLES: Record<string, string> = {
  white: '#FFFFFF',
  black: '#000000',
  'gray-200': '#DDE0E6',
  'gray-400': '#BABCBE',
  'gray-500': '#8B909A',
  'gray-600': '#757575',
  'gray-700': '#14151B',
  'interactive-light': '#56B3E5',
  'interactive-medium': '#2191CD',
  'interactive-dark': '#005B8C',
  'interactive-faint': '#F5F7FA',
  'interactive-faint-hover': '#EBEFF7',
  'yellow-bright': '#FCFF4D',
  'yellow-medium': '#FEFFB0',
  'yellow-dull': '#E6E6D1',
  'cell-warning': '#C9772E',
  'cell-error': '#FF251A',
  'text-error': '#E2655F',
  'blue-bright': '#4BC0FF',
  'blue-medium': '#CFEEFF',
  // 14-S11: the keyboard focus ring.
  cyan: '#00F0FF',
};

// style -> the variable it references
const STYLES: Record<string, string> = {
  'build-cell-on': 'white',
  'build-cell-off': 'gray-200',
  'build-cell-border': 'gray-400',
  'build-cell-selected-cell': 'yellow-bright',
  'build-cell-selected-row-on': 'yellow-medium',
  'build-cell-selected-row-off': 'yellow-dull',
  'preview-cell-on': 'white',
  'preview-cell-off': 'gray-700',
  'preview-cell-warning': 'cell-warning',
  'preview-cell-error': 'cell-error',
  'play-cell-on': 'white',
  'play-cell-off': 'gray-700',
  'play-cell-border': 'gray-500',
  'play-cell-selected-cell': 'yellow-bright',
  'play-cell-selected-row': 'blue-medium',
  'hint-cell-selected': 'blue-medium',
  primary: 'black',
  muted: 'gray-500',
  'link-muted': 'interactive-light',
  highlight: 'blue-bright',
  error: 'text-error',
  subtle: 'gray-600',
  inverse: 'white',
  'line-muted': 'gray-200',
  'line-highlight': 'blue-bright',
  'line-dark': 'gray-600',
  'fill-muted': 'gray-200',
  'button-fill': 'interactive-light',
  'button-hover': 'interactive-medium',
  'button-active': 'interactive-dark',
  'button-alternate-border': 'gray-500',
  'button-alternate-hover': 'gray-500',
  'puzzle-row': 'interactive-faint',
  'puzzle-row-hover': 'interactive-faint-hover',
  'modal-background': 'white',
  'modal-title-background': 'yellow-bright',
  logo: 'gray-400',
  'logo-cell': 'white',
  masthead: 'white',
  // 14-S11: the keyboard focus ring.
  'focus-ring': 'cyan',
};

// The one translucent style: black at 40% opacity.
const BACKDROP = 'modal-backdrop';
const BACKDROP_VARIABLE = 'black';
const BACKDROP_ALPHA = 0.4;

const ALL_STYLES = [...Object.keys(STYLES), BACKDROP];

function variableOf(style: string) {
  return style === BACKDROP ? BACKDROP_VARIABLE : STYLES[style];
}

// The old tokens keep their committed values until epic 14 deletes them.
const OLD_COLOR_TOKENS: Record<string, string> = {
  '--color-background': '#ffffff',
  '--color-foreground': '#14151b',
  '--color-ink-2': '#565b67',
  '--color-ink-3': '#9ba1ad',
  '--color-rule': '#ecedf1',
  '--color-rule-strong': '#dee0e6',
  '--color-hover-tint': '#f3f4f7',
  '--color-panel-tint': '#f6faf8',
  '--color-accent': '#1f9d6b',
  '--color-accent-hover': '#178257',
  '--color-ok-tint': '#e4f6ee',
  '--color-grid-empty': '#dde0e6',
  '--color-grid-line-build': '#c2c2c2',
  '--color-grid-line-play': '#616161',
  '--color-cell-fill': '#dff3ea',
  '--color-selected': '#fcff5c',
  '--color-slot': '#f1f1ea',
  '--color-slot-content': '#ffffe2',
  '--color-required': '#ff251a',
  '--color-recommended': '#c9772e',
  '--color-locked-letter': '#e7e9ee',
  '--color-editable-letter': '#fff1c2',
  '--color-incomplete': '#9ba1ad',
};

const SENTINEL = '#123456';

type Rgba = { r: number; g: number; b: number; a: number };

/**
 * Parses the forms getComputedStyle reports for a colour: rgb(), rgba() and
 * color(srgb ...) (which color-mix() and relative colours can produce).
 */
function parseColor(value: string): Rgba {
  const rgb = value.match(/^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/);
  if (rgb) {
    return {
      r: Number(rgb[1]),
      g: Number(rgb[2]),
      b: Number(rgb[3]),
      a: alpha(rgb[4]),
    };
  }
  const srgb = value.match(/^color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+%?))?\s*\)$/);
  if (srgb) {
    return {
      r: Math.round(Number(srgb[1]) * 255),
      g: Math.round(Number(srgb[2]) * 255),
      b: Math.round(Number(srgb[3]) * 255),
      a: alpha(srgb[4]),
    };
  }
  throw new Error(`unparseable colour: "${value}"`);
}

function alpha(raw: string | undefined) {
  if (raw === undefined) return 1;
  return raw.endsWith('%') ? Number(raw.slice(0, -1)) / 100 : Number(raw);
}

function expectColor(actual: Rgba, expected: Rgba, label: string) {
  expect({ r: actual.r, g: actual.g, b: actual.b }, label).toEqual({
    r: expected.r,
    g: expected.g,
    b: expected.b,
  });
  expect(actual.a, `${label} alpha`).toBeCloseTo(expected.a, 2);
}

function hexToRgba(hex: string, a = 1): Rgba {
  const n = parseInt(hex.replace('#', ''), 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255, a };
}

/** The colour a CSS value (a literal or a var() reference) paints as a background. */
async function resolve(page: Page, cssValue: string) {
  const raw = await page.evaluate((value) => {
    const probe = document.createElement('div');
    probe.style.backgroundColor = value;
    document.body.appendChild(probe);
    const resolved = getComputedStyle(probe).backgroundColor;
    probe.remove();
    return resolved;
  }, cssValue);
  return parseColor(raw);
}

async function bgOf(locator: ReturnType<Page['locator']>) {
  return parseColor(await locator.evaluate((el) => getComputedStyle(el).backgroundColor));
}

function setVariable(page: Page, name: string, value: string) {
  return page.evaluate(
    ([n, v]) => document.documentElement.style.setProperty(n, v),
    [name, value] as const
  );
}

function clearVariable(page: Page, name: string) {
  return page.evaluate((n) => document.documentElement.style.removeProperty(n), name);
}

function expectedStyle(style: string, hex: string) {
  return hexToRgba(hex, style === BACKDROP ? BACKDROP_ALPHA : 1);
}

function variableRow(page: Page, name: string) {
  return page.locator(`[data-testid="sg-color-variable"][data-variable="${name}"]`);
}

function styleRow(page: Page, name: string) {
  return page.locator(`[data-testid="sg-color-style"][data-style="${name}"]`);
}

// --- F1-1: the palette variables ---
test.describe('F1-1 color variables', () => {
  test('every variable resolves to its hex value app-wide', async ({ page }) => {
    await page.goto('/puzzles');

    for (const [name, hex] of Object.entries(VARIABLES)) {
      expectColor(await resolve(page, `var(--palette-${name})`), hexToRgba(hex), `--palette-${name}`);
    }
  });
});

// --- F1-2: the color styles ---
test.describe('F1-2 color styles', () => {
  test('every style resolves to its variable app-wide', async ({ page }) => {
    await page.goto('/puzzles');

    for (const style of ALL_STYLES) {
      expectColor(
        await resolve(page, `var(--color-${style})`),
        expectedStyle(style, VARIABLES[variableOf(style)]),
        `--color-${style}`
      );
    }
  });

  test('each style follows its variable when the variable is edited live', async ({ page }) => {
    await page.goto('/style-guide');

    for (const style of ALL_STYLES) {
      const variable = `--palette-${variableOf(style)}`;
      await setVariable(page, variable, SENTINEL);

      const expected = expectedStyle(style, SENTINEL);
      expectColor(await resolve(page, `var(--color-${style})`), expected, `--color-${style} after editing ${variable}`);
      // the catalog paints with the token, so it repaints too
      expectColor(
        await bgOf(styleRow(page, style).getByTestId('sg-swatch')),
        expected,
        `${style} swatch after editing ${variable}`
      );

      await clearVariable(page, variable);
      expectColor(
        await resolve(page, `var(--color-${style})`),
        expectedStyle(style, VARIABLES[variableOf(style)]),
        `--color-${style} after restoring ${variable}`
      );
    }
  });
});

// --- F1-3: the old tokens are untouched ---
test.describe('F1-3 old tokens unchanged', () => {
  test('every old color token keeps its committed value', async ({ page }) => {
    await page.goto('/puzzles');

    for (const [token, hex] of Object.entries(OLD_COLOR_TOKENS)) {
      expectColor(await resolve(page, `var(${token})`), hexToRgba(hex), token);
    }
  });
});

// --- F1-4: the catalog shows the palette ---
test.describe('F1-4 style-guide color catalog', () => {
  test('every variable is shown by name and hex, swatched in its color', async ({ page }) => {
    await page.goto('/style-guide');
    await expect(page.getByTestId('sg-colors')).toBeVisible();
    await expect(page.getByTestId('sg-color-variable')).toHaveCount(Object.keys(VARIABLES).length);

    for (const [name, hex] of Object.entries(VARIABLES)) {
      const row = variableRow(page, name);
      await expect(row, `expected a row for ${name}`).toBeVisible();
      await expect(row).toContainText(name);
      await expect(row).toContainText(new RegExp(hex.replace('#', ''), 'i'));
      expectColor(await bgOf(row.getByTestId('sg-swatch')), hexToRgba(hex), `${name} swatch`);
    }
  });

  test('every style is shown with its variable, swatched in its color', async ({ page }) => {
    await page.goto('/style-guide');
    await expect(page.getByTestId('sg-color-style')).toHaveCount(ALL_STYLES.length);

    for (const style of ALL_STYLES) {
      const row = styleRow(page, style);
      await expect(row, `expected a row for ${style}`).toBeVisible();
      await expect(row).toContainText(style);
      await expect(row).toContainText(variableOf(style));
      expectColor(
        await bgOf(row.getByTestId('sg-swatch')),
        expectedStyle(style, VARIABLES[variableOf(style)]),
        `${style} swatch`
      );
    }

    await expect(styleRow(page, BACKDROP)).toContainText('40%');
  });
});

// --- F1-5: the live token editor is gone ---
test.describe('F1-5 plain catalog', () => {
  test('the live token editor and its controls are gone', async ({ page }) => {
    await page.goto('/style-guide');
    await expect(page.getByTestId('sg-colors')).toBeVisible();

    for (const testid of [
      'token-pane',
      'token-tab',
      'token-tab-panel',
      'color-picker',
      'size-control',
      'weight-control',
      'utility-control',
      'font-family-control',
      'font-url-input',
    ]) {
      await expect(page.getByTestId(testid), `expected no ${testid}`).toHaveCount(0);
    }
    await expect(page.locator('input[type="color"]')).toHaveCount(0);
  });

  for (const viewport of [
    { width: 1280, height: 800 },
    { width: 375, height: 667 },
  ]) {
    test(`no horizontal overflow at ${viewport.width}px`, async ({ page }) => {
      await page.setViewportSize(viewport);
      await page.goto('/style-guide');

      await expect(page.getByTestId('sg-colors')).toBeVisible();
      const overflow = await page.evaluate(
        () => document.documentElement.scrollWidth > document.documentElement.clientWidth
      );
      expect(overflow).toBe(false);
    });
  }
});
